`timescale 1ns / 1ps
`default_nettype none

// AES forward S-box -- composite-field arithmetic implementation.
//
// MACHINE-GENERATED by sim/gen_sbox_cf.py -- do not hand-edit.
// The generator proves equivalence with the original table S-box
// for all 256 inputs (Python asserts) before emitting this file;
// sim/tb_sbox_equiv.v re-proves it in simulation.
//
// Construction:
//   sbox(a) = A( inv(a) ), A = AES affine transform, GF(2^8)/0x11b.
//   The GF(2^8) inverse is computed in the composite field
//   GF((2^4)^2): GF(2^4) uses polynomial 0x13; elements (h,l) mean
//   h*z + l with z^2 = z + phi, phi = 4'h8 (trace 1 over GF(2)).
//   delta maps the GF(2^8) polynomial basis onto the composite
//   basis via alpha = 8'h20, a root of x^8+x^4+x^3+x+1
//   found exhaustively in the composite field:
//     delta(sum b_i x^i) = sum b_i alpha^i   (GF(2)-linear XOR net)
//   Composite inversion (all sub-ops in GF(2^4)):
//     d = phi*h^2 + h*l + l^2;  inv_h = h * d^-1;
//     inv_l = (h + l) * d^-1;   (0,0) -> (0,0), guarded by d == 0.
//   The output passes through delta^-1 followed by the affine
//   transform A, fused into one GF(2)-linear XOR network + 0x63.
//
// Purely combinational: no clock, state, or added cycle latency.
module aes_sbox (
    input  wire [7:0] data_in,
    output reg  [7:0] data_out
);

    localparam [3:0] PHI = 4'h8;

    // ---- GF(2^4) multiply: shift-and-reduce with polynomial 0x13 ----
    function [3:0] gf_mul4;
        input [3:0] a;
        input [3:0] b;
        reg [3:0] aa;
        reg [3:0] bb;
        reg [3:0] p;
        integer i;
        begin
            aa = a; bb = b; p = 4'h0;
            for (i = 0; i < 4; i = i + 1) begin
                if (bb[0]) p = p ^ aa;
                aa = {aa[2:0], 1'b0} ^ (aa[3] ? 4'h3 : 4'h0);
                bb = {1'b0, bb[3:1]};
            end
            gf_mul4 = p;
        end
    endfunction

    // ---- GF(2^4) square ----
    function [3:0] gf_sq4;
        input [3:0] x;
        begin
            gf_sq4 = gf_mul4(x, x);
        end
    endfunction

    // ---- GF(2^4) multiply by the constant phi ----
    function [3:0] gf_mul_phi;
        input [3:0] x;
        begin
            gf_mul_phi = gf_mul4(x, PHI);
        end
    endfunction

    // ---- GF(2^4) inverse via the power chain x^14 (x^2,x^3,x^6,x^7,x^14);
    // ---- gf_inv4(0) = 0 because every term of the chain is 0. ----
    function [3:0] gf_inv4;
        input [3:0] x;
        reg [3:0] x2;
        reg [3:0] x3;
        reg [3:0] x6;
        reg [3:0] x7;
        begin
            x2 = gf_sq4(x);
            x3 = gf_mul4(x2, x);
            x6 = gf_sq4(x3);
            x7 = gf_mul4(x6, x);
            gf_inv4 = gf_sq4(x7);
        end
    endfunction

    reg [7:0] comp_in;    // delta(data_in): {h, l}
    reg [3:0] d;
    reg [3:0] d_inv;
    reg [3:0] inv_h;
    reg [3:0] inv_l;
    reg [7:0] comp_inv;   // composite inverse: {inv_h, inv_l}

    always @* begin
        // delta: GF(2)-linear XOR network generated from the delta matrix
        comp_in[0] = data_in[0] ^ data_in[5] ^ data_in[7];
        comp_in[1] = data_in[2];
        comp_in[2] = data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7];
        comp_in[3] = data_in[3] ^ data_in[4];
        comp_in[4] = data_in[4] ^ data_in[5] ^ data_in[6];
        comp_in[5] = data_in[1] ^ data_in[4] ^ data_in[6] ^ data_in[7];
        comp_in[6] = data_in[2] ^ data_in[3] ^ data_in[5] ^ data_in[7];
        comp_in[7] = data_in[5] ^ data_in[7];

        // composite-field inversion in GF(2^4)
        d = gf_mul_phi(gf_sq4(comp_in[7:4]))
          ^ gf_mul4(comp_in[7:4], comp_in[3:0])
          ^ gf_sq4(comp_in[3:0]);
        d_inv = gf_inv4(d);
        // d == 0 exactly when (h,l) == (0,0): guard forces (0,0) -> (0,0)
        inv_h = (d == 4'h0) ? 4'h0 : gf_mul4(comp_in[7:4], d_inv);
        inv_l = (d == 4'h0) ? 4'h0
              : gf_mul4(comp_in[7:4] ^ comp_in[3:0], d_inv);
        comp_inv = {inv_h, inv_l};

        // delta^-1 followed by affine A: fused XOR network + 0x63 constant
        data_out[0] = comp_inv[0] ^ comp_inv[2] ^ comp_inv[6] ^ 1'b1;
        data_out[1] = comp_inv[0] ^ comp_inv[1] ^ comp_inv[2] ^ comp_inv[3] ^ comp_inv[4] ^ comp_inv[5] ^ 1'b1;
        data_out[2] = comp_inv[0] ^ comp_inv[3] ^ comp_inv[5] ^ comp_inv[6];
        data_out[3] = comp_inv[0] ^ comp_inv[2] ^ comp_inv[5];
        data_out[4] = comp_inv[0] ^ comp_inv[1] ^ comp_inv[3] ^ comp_inv[4] ^ comp_inv[5];
        data_out[5] = comp_inv[1] ^ comp_inv[2] ^ comp_inv[3] ^ comp_inv[5] ^ comp_inv[6] ^ comp_inv[7] ^ 1'b1;
        data_out[6] = comp_inv[4] ^ comp_inv[6] ^ comp_inv[7] ^ 1'b1;
        data_out[7] = comp_inv[1] ^ comp_inv[2];
    end

endmodule

`default_nettype wire
